</head>
<body>
    <canvas id="canvas"></canvas>
    <div id="info">FPS: 0 | Press W for wireframe, P to pause</div>

    <script>
        // 1. Define cube vertices and faces
        const vertices = [
            // 8 vertices of the cube
            [-1, -1, -1], // 0
            [1, -1, -1],  // 1
            [1, 1, -1],   // 2
            [-1, 1, -1],  // 3
            [-1, -1, 1],  // 4
            [1, -1, 1],   // 5
            [1, 1, 1],    // 6
            [-1, 1, 1]    // 7
        ];

        // Define faces as triangles (each face split into 2 triangles)
        const faces = [
            // Front face (z = -1)
            [0, 1, 2], [0, 2, 3],
            // Back face (z = 1)
            [4, 7, 6], [4, 6, 5],
            // Right face (x = 1)
            [1, 5, 6], [1, 6, 2],
            // Left face (x = -1)
            [7, 3, 0], [7, 0, 4],
            // Top face (y = 1)
            [3, 2, 6], [3, 6, 7],
            // Bottom face (y = -1)
            [0, 4, 5], [0, 5, 1]
        ];

        // 2. Implement 3D transformation pipeline
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');
        const aspectRatio = window.innerWidth / window.innerHeight;
        canvas.width = Math.min(window.innerWidth - 20, 800);
        canvas.height = Math.min(window.innerHeight - 20, 600);

        // Projection parameters
        const fov = 500;
        const centerX = canvas.width / 2;
        const centerY = canvas.height / 2;

        // Rotation state
        let angleX = 0;
        let angleY = 0;
        let angleZ = 0;
        let isPaused = false;
        let showWireframe = false;

        // Light source position (moving in a circle)
        let lightAngle = 0;
        const lightRadius = 3;
        const lightSpeed = 0.01;

        // Rotation matrices
        function rotateX(point, angle) {
            const cos = Math.cos(angle);
            const sin = Math.sin(angle);
            return [
                point[0],
                point[1] * cos - point[2] * sin,
                point[1] * sin + point[2] * cos
            ];
        }

        function rotateY(point, angle) {
            const cos = Math.cos(angle);
            const sin = Math.sin(angle);
            return [
                point[0] * cos + point[2] * sin,
                point[1],
                -point[0] * sin + point[2] * cos
            ];
        }

        function rotateZ(point, angle) {
            const cos = Math.cos(angle);
            const sin = Math.sin(angle);
            return [
                point[0] * cos - point[1] * sin,
                point[0] * sin + point[1] * cos,
                point[2]
            ];
        }

        // Perspective projection
        function project(point) {
            const z = point[2] + fov;
            if (z <= 0) return null; // Behind the camera
            const scale = fov / z;
            return [
                point[0] * scale + centerX,
                point[1] * scale + centerY,
                z
            ];
        }

        // Backface culling
        function isFaceVisible(face, transformedVertices) {
            // Get three points of the triangle
            const p1 = transformedVertices[face[0]];
            const p2 = transformedVertices[face[1]];
            const p3 = transformedVertices[face[2]];

            // Calculate normal vector using cross product
            const v1 = [
                p2[0] - p1[0],
                p2[1] - p1[1],
                p2[2] - p1[2]
            ];

            const v2 = [
                p3[0] - p1[0],
                p3[1] - p1[1],
                p3[2] - p1[2]
            ];

            // Cross product
            const normal = [
                v1[1] * v2[2] - v1[2] * v2[1],
                v1[2] * v2[0] - v1[0] * v2[2],
                v1[0] * v2[1] - v1[1] * v2[0]
            ];

            // Dot product with view direction (0,0,-1) - looking down negative z
            const dotProduct = normal[2];

            // Backface culling: if normal is pointing away from viewer (negative z), skip
            return dotProduct > 0;
        }

        // 3. Implement Gouraud shading
        // Lambert's law: diffuse lighting
        function calculateLighting(vertex, lightDir) {
            // Normalize vertex normal (for a cube, use the face normal)
            // For cube vertices, we'll approximate the normal based on the vertex position
            const normal = [
                vertex[0],
                vertex[1],
                vertex[2]
            ];

            // Normalize normal
            const length = Math.sqrt(normal[0] * normal[0] + normal[1] * normal[1] + normal[2] * normal[2]);
            if (length > 0) {
                normal[0] /= length;
                normal[1] /= length;
                normal[2] /= length;
            }

            // Normalize light direction
            const lightLength = Math.sqrt(lightDir[0] * lightDir[0] + lightDir[1] * lightDir[1] + lightDir[2] * lightDir[2]);
            if (lightLength > 0) {
                lightDir[0] /= lightLength;
                lightDir[1] /= lightLength;
                lightDir[2] /= lightLength;
            }

            // Lambert's law: diffuse component = max(0, N · L)
            const dotProduct = normal[0] * lightDir[0] + normal[1] * lightDir[1] + normal[2] * lightDir[2];
            return Math.max(0, dotProduct);
        }

        // Gouraud shading: interpolate lighting across triangle
        function drawTriangle(p1, p2, p3, l1, l2, l3) {
            // If any point is behind camera, skip
            if (p1 === null || p2 === null || p3 === null) return;

            // Create gradient between vertices
            const minX = Math.min(p1[0], p2[0], p3[0]);
            const maxX = Math.max(p1[0], p2[0], p3[0]);
            const minY = Math.min(p1[1], p2[1], p3[1]);
            const maxY = Math.max(p1[1], p2[1], p3[1]);

            // For each pixel in the bounding box
            for (let x = Math.floor(minX); x <= Math.ceil(maxX); x++) {
                for (let y = Math.floor(minY); y <= Math.ceil(maxY); y++) {
                    // Check if point is inside triangle using barycentric coordinates
                    const w1 = ((p2[1] - p3[1]) * (x - p3[0]) + (p3[0] - p2[0]) * (y - p3[1])) /
                               ((p2[1] - p3[1]) * (p1[0] - p3[0]) + (p3[0] - p2[0]) * (p1[1] - p3[1]));
                    const w2 = ((p3[1] - p1[1]) * (x - p3[0]) + (p1[0] - p3[0]) * (y - p3[1])) /
                               ((p2[1] - p3[1]) * (p1[0] - p3[0]) + (p3[0] - p2[0]) * (p1[1] - p3[1]));
                    const w3 = 1 - w1 - w2;

                    // Check if point is inside triangle
                    if (w1 >= 0 && w2 >= 0 && w3 >= 0) {
                        // Interpolate lighting
                        const light = w1 * l1 + w2 * l2 + w3 * l3;

                        // Calculate color based on lighting (white with intensity)
                        const intensity = Math.floor(light * 255);
                        const color = Math.max(0, Math.min(255, intensity));

                        // Draw pixel
                        ctx.fillStyle = `rgb(${color}, ${color}, ${color})`;
                        ctx.fillRect(x, y, 1, 1);
                    }
                }
            }
        }

        // 4. Add moving light source
        function updateLightSource() {
            lightAngle += lightSpeed;
            const lightX = lightRadius * Math.cos(lightAngle);
            const lightY = lightRadius * Math.sin(lightAngle);
            const lightZ = lightRadius * Math.sin(lightAngle * 0.5);

            return [lightX, lightY, lightZ];
        }

        // 5. Implement UI controls
        document.addEventListener('keydown', function(event) {
            if (event.key === 'w' || event.key === 'W') {
                showWireframe = !showWireframe;
            } else if (event.key === 'p' || event.key === 'P') {
                isPaused = !isPaused;
            }
        });

        // 6. Implement FPS counter
        let frameCount = 0;
        let lastTime = performance.now();
        let fps = 0;

        function updateFPS() {
            frameCount++;
            const currentTime = performance.now();
            const deltaTime = currentTime - lastTime;

            if (deltaTime > 1000) {
                fps = Math.round((frameCount * 1000) / deltaTime);
                frameCount = 0;
                lastTime = currentTime;
                document.getElementById('info').textContent = `FPS: ${fps} | Press W for wireframe, P to pause`;
            }
        }

        // 7. Main animation loop
        function animate() {
            if (!isPaused) {
                // Update rotation angles
                angleX += 0.01;
                angleY += 0.015;
                angleZ += 0.008;

                // Update light source
                const lightPos = updateLightSource();

                // Clear canvas
                ctx.clearRect(0, 0, canvas.width, canvas.height);

                // Transform vertices
                const transformedVertices = [];
                for (let i = 0; i < vertices.length; i++) {
                    let vertex = [...vertices[i]];

                    // Apply rotations
                    vertex = rotateX(vertex, angleX);
                    vertex = rotateY(vertex, angleY);
                    vertex = rotateZ(vertex, angleZ);

                    // Project to 2D
                    vertex = project(vertex);

                    transformedVertices.push(vertex);
                }

                // Calculate lighting for each vertex
                const vertexLighting = [];
                for (let i = 0; i < vertices.length; i++) {
                    const vertex = vertices[i];
                    const lighting = calculateLighting(vertex, lightPos);
                    vertexLighting.push(lighting);
                }

                // Draw triangles
                for (let i = 0; i < faces.length; i++) {
                    const face = faces[i];

                    // Backface culling
                    if (!isFaceVisible(face, transformedVertices)) continue;

                    // Get transformed vertices and lighting values
                    const p1 = transformedVertices[face[0]];
                    const p2 = transformedVertices[face[1]];
                    const p3 = transformedVertices[face[2]];
                    const l1 = vertexLighting[face[0]];
                    const l2 = vertexLighting[face[1]];
                    const l3 = vertexLighting[face[2]];

                    // Draw Gouraud shaded triangle
                    drawTriangle(p1, p2, p3, l1, l2, l3);

                    // Draw wireframe if enabled
                    if (showWireframe) {
                        ctx.strokeStyle = '#ffffff';
                        ctx.lineWidth = 0.5;
                        ctx.beginPath();
                        ctx.moveTo(p1[0], p1[1]);
                        ctx.lineTo(p2[0], p2[1]);
                        ctx.lineTo(p3[0], p3[1]);
                        ctx.closePath();
                        ctx.stroke();
                    }
                }
            }

            // Update FPS
            updateFPS();

            // Request next frame
            requestAnimationFrame(animate);
        }

        // Start animation
        animate();

        // Handle window resize
        window.addEventListener('resize', function() {
            const newWidth = Math.min(window.innerWidth - 20, 800);
            const newHeight = Math.min(window.innerHeight - 20, 600);
            canvas.width = newWidth;
            canvas.height = newHeight;
            centerX = canvas.width / 2;
            centerY = canvas.height / 2;
        });
    </script>
</body>
